import { createBubbleCover } from './bubble-reveal.js';
import { createPopState } from '../app/dgn-pop.js';
import { dgnBadgePath, dgnDisplaySymbol, dgnColorName } from '../app/dgn-traits.js';
import { sfxDgnPop, stopDgnPops } from '../app/jackpot-sfx.js';

const name = (q, t) => t ? `${dgnColorName(t.col)} ${dgnDisplaySymbol(q, t.sym, t.col)}` : 'unavailable';

/**
 * Shared by every Degenerette source. Covered house art/labels are not mounted.
 * `layout: 'mystery'` seats card 1 in the centre of a fixed three-slot frame so
 * a FLIP lane's two bonus cards open beside it without moving it, and every
 * mystery card shows the same frame before its currency lands.
 */
export function mountPopBoards(host, rows, {
  footer = null, availableCount = rows.length, layout = null, paginate = false,
  ticketPayout = () => null,
  onChange = () => {}, onRevealAll = () => {},
} = {}) {
  const doc = host.ownerDocument || document;
  const state = createPopState(rows);
  const cleanups = [];
  // Decode result art while the covers are still up. The first click should
  // not wait on an SVG fetch/rasterization; concealed results stay out of DOM.
  const badgeSources = new Map();
  const badgeSource = (q, trait) => {
    const key = `${q}:${trait.sym}:${trait.col}`;
    if (!badgeSources.has(key)) badgeSources.set(key, dgnBadgePath(q, trait.sym, trait.col));
    return badgeSources.get(key);
  };
  const preloaded = new Set();
  for (const board of state.boards) board.quadrants.forEach((quadrant, q) => {
    if (!quadrant.house) return;
    const src = badgeSource(q, quadrant.house);
    if (preloaded.has(src)) return;
    preloaded.add(src);
    const art = doc.createElement('img');
    art.decoding = 'async';
    art.src = src;
    art.decode?.().catch(() => {});
  });
  let disposed = false;
  let locked = false;
  let available = Math.min(rows.length, availableCount);
  const phoneQuery = paginate ? doc.defaultView?.matchMedia?.('(max-width: 768px), (max-width: 1000px) and (max-height: 500px)') : null;
  let compact = Boolean(phoneQuery?.matches);
  let page = 0;
  const pageRange = () => {
    const start = compact ? page * 4 : 0;
    return { start, end: Math.min(available, compact ? start + 4 : available) };
  };
  const el = (tag, cls, text) => {
    const node = doc.createElement(tag);
    node.className = cls;
    if (text != null) node.textContent = text;
    return node;
  };
  const listen = (node, fn) => {
    node.addEventListener('click', fn);
    cleanups.push(() => node.removeEventListener('click', fn));
  };
  const badge = (q, trait, cls) => {
    const img = el('img', cls);
    img.src = badgeSource(q, trait);
    img.alt = '';
    img.draggable = false;
    return img;
  };
  // A luminous ring stays with the player's chosen symbol, including its
  // corner reference after reveal. It never marks the house result.
  const championMark = () => {
    const mark = el('span', 'dgn-pop__champion');
    mark.setAttribute('aria-hidden', 'true');
    return mark;
  };
  const root = el('section', 'dgn-pop');
  const hint = el('p', 'dgn-pop__hint', 'Tap a quadrant · Flame reveals card');
  root.appendChild(hint);
  if (state.boards.some(board => board.hero != null)) {
    const guide = el('p', 'dgn-pop__champion-guide');
    guide.appendChild(championMark());
    guide.appendChild(el('span', '', 'Champion · wild color'));
    root.appendChild(guide);
  }
  const grid = el('div', 'dgn-pop__grid');
  if (layout) grid.dataset.layout = layout;
  const viewport = el('div', `dgn-pop__viewport${footer ? ' dgn-pop__viewport--winnings' : ''}`);
  viewport.tabIndex = 0;
  viewport.setAttribute('role', 'region');
  viewport.setAttribute('aria-label', 'Cards');
  viewport.appendChild(grid);
  // A footer (the payout bar) rides directly under the cards, centred with them.
  if (footer) viewport.appendChild(footer);
  const pager = el('nav', 'dgn-pop__pager');
  pager.setAttribute('aria-label', 'Ticket pages');
  const previous = el('button', 'dgn-pop__previous', '‹ Back');
  const pageLabel = el('span', 'dgn-pop__page-label');
  pageLabel.setAttribute('aria-live', 'polite');
  const nextPage = el('button', 'dgn-pop__next', 'Next ›');
  for (const button of [previous, nextPage]) {
    button.type = 'button';
    button.setAttribute('data-button-feedback', 'off');
  }
  listen(previous, event => { event.stopPropagation(); goToPage(page - 1); });
  listen(nextPage, event => { event.stopPropagation(); goToPage(page + 1); });
  pager.appendChild(previous);
  pager.appendChild(pageLabel);
  pager.appendChild(nextPage);
  root.appendChild(pager);
  root.appendChild(viewport);
  const cards = state.boards.map((board, index) => {
    const card = el('article', 'dgn-pop__card');
    const ticket = el('div', 'dgn-pop__ticket');
    const cells = board.quadrants.map((quadrant, q) => {
      const cell = el('button', `dgn-pop__cell dgn-pop__cell--q${q}`);
      cell.type = 'button';
      cell.setAttribute('data-button-feedback', 'off');
      cell.setAttribute('aria-label', `Card ${index + 1}, ${name(q, quadrant.player)}${quadrant.hero ? ', your champion' : ''}. Reveal quadrant`);
      const cover = createBubbleCover(doc, {
        badgeSrc: badgeSource(q, quadrant.player),
        color: '#cad9d9',
        durationMs: 140,
      });
      if (quadrant.hero) {
        cell.dataset.champion = 'covered';
        cover.element.querySelector('.bubble-reveal__badge').appendChild(championMark());
      }
      cell.appendChild(cover.element);
      cleanups.push(() => cover.dispose());
      cell.bubbleCover = cover;
      listen(cell, event => { event.stopPropagation(); reveal(index, 1 << q, event); });
      ticket.appendChild(cell);
      return cell;
    });
    const flame = el('button', 'dgn-pop__flame');
    flame.type = 'button';
    flame.setAttribute('data-button-feedback', 'off');
    flame.setAttribute('aria-label', `Reveal this card (${index + 1})`);
    const mark = el('span', 'dgn-pop__flame-mark');
    mark.setAttribute('aria-hidden', 'true');
    flame.appendChild(mark);
    listen(flame, event => { event.stopPropagation(); reveal(index); });
    ticket.appendChild(flame);
    card.appendChild(ticket);
    const bonus = layout === 'mystery' && index > 0;
    const number = el('span', 'dgn-pop__number', bonus ? null : `CARD ${index + 1}`);
    if (bonus) {
      card.classList.add('dgn-pop__card--bonus');
      number.appendChild(el('span', 'dgn-pop__bonus-tag', 'BONUS'));
      number.appendChild(el('span', 'dgn-pop__number-text', `CARD ${index + 1}`));
    }
    card.appendChild(number);
    const gold = el('span', 'dgn-pop__gold-total');
    gold.hidden = true;
    card.appendChild(gold);
    grid.appendChild(card);
    return { card, ticket, cells, flame, gold, number, available: index < available };
  });
  const all = el('button', 'dgn-pop__all', 'REVEAL ALL');
  all.type = 'button';
  all.setAttribute('data-button-feedback', 'off');
  listen(all, event => {
    event.stopPropagation();
    if (disposed || locked) return;
    if (!compact || available <= 4) { revealAll(); return; }
    const { start, end } = pageRange();
    const masks = state.snapshot().masks;
    if (masks.slice(start, end).every(mask => mask === 15)) {
      const pending = masks.findIndex((mask, i) => i < available && mask !== 15);
      goToPage(page * 4 + 4 < available ? page + 1 : Math.floor(pending / 4));
    } else {
      commit(cards.flatMap((_, i) => i >= start && i < end ? state.reveal(i) : []));
    }
  });
  root.appendChild(all);
  host.appendChild(root);

  let painted = false;
  function paint(added = [], event) {
    const next = state.snapshot();
    const { start, end } = pageRange();
    const pageComplete = next.masks.slice(start, end).every(mask => mask === 15);
    const changed = new Set(added.map(item => item.board));
    const batch = added.length > 1;
    const offscreen = new Set();
    // Hiding/disabling the focused control makes Chrome synchronously repair
    // focus, laying out every result just inserted by this click. Hand focus
    // to the stable scroll region BEFORE any result DOM writes instead.
    const focused = doc.activeElement;
    if ((focused === all && (next.complete || available <= 1 || locked))
      || cards.some((card, i) => focused === card.flame && (locked || next.masks[i] === 15))) {
      viewport.focus?.({ preventScroll: true });
    }
    if (added.length > 4) {
      // Read all bounds before touching the DOM. A mass reveal still settles
      // every card immediately, but only visible tickets need effects.
      const bounds = viewport.getBoundingClientRect();
      const top = Math.max(0, bounds.top);
      const bottom = Math.min(bounds.top + bounds.height, doc.defaultView?.innerHeight ?? Infinity);
      for (const index of changed) {
        const ticket = cards[index].ticket.getBoundingClientRect();
        if (cards[index].card.hidden || ticket.top + ticket.height <= top || ticket.top >= bottom) offscreen.add(index);
      }
    }
    for (const item of added) {
      const cell = cards[item.board].cells[item.quadrant];
      const cover = cell.bubbleCover;
      // A single puncture measures its origin before any result DOM writes.
      // Grouped pops perform no layout reads at all inside this loop.
      cover.pop(event, { batch, instant: offscreen.has(item.board), onComplete: () => {
        if (!disposed && item.points > 0 && !offscreen.has(item.board)) cell.classList.add('is-match');
      } });
      // Keep the film above the newly mounted result until its puncture finishes.
      cell.classList.add('is-open');
      if (item.points != null) cell.dataset.points = String(item.points);
      if (item.house) cell.appendChild(badge(item.quadrant, item.house, 'dgn-pop__badge'));
      else cell.appendChild(el('span', 'dgn-pop__unknown', '?'));
      const championMatch = item.hero && item.symbolMatch;
      const player = el('span', 'dgn-pop__player');
      player.appendChild(badge(item.quadrant, item.player, 'dgn-pop__player-art'));
      if (item.hero) {
        player.classList.add('is-champion');
        player.appendChild(championMark());
        cell.dataset.champion = item.house ? (championMatch ? 'match' : 'miss') : 'unknown';
      }
      cell.appendChild(player);
      if (item.points > 0) {
        const increment = el('span', 'dgn-pop__increment', `+${item.points}`);
        increment.setAttribute('aria-hidden', 'true');
        cell.appendChild(increment);
      }
      if (item.house?.wild) {
        cell.classList.add('is-wild');
      }
      const matches = [item.symbolMatch ? 'symbol match' : '', item.colorMatch ? (item.player.wild || item.house?.wild ? 'color match (wild)' : 'color match') : ''].filter(Boolean).join(', ');
      const championDetail = item.hero
        ? championMatch ? 'Champion symbol matched. '
          : item.house ? 'Champion symbol did not match. ' : 'Champion result unavailable. '
        : '';
      const detail = `Card ${item.board + 1}. You: ${name(item.quadrant, item.player)}. House: ${name(item.quadrant, item.house)}. ${matches || 'No match'}. ${championDetail}${item.points == null ? 'Recorded score added when card completes.' : `${item.points} points.`}${item.house?.wild ? ' House wild.' : ''}`;
      cell.setAttribute('aria-label', detail);
      cell.title = detail;
    }
    cards.forEach((card, i) => {
      // Ordinary taps update their own card, not every covered card in a set.
      // Empty paints are explicit availability/lock updates and visit them all.
      if (added.length && !changed.has(i)) return;
      if (batch) card.card.classList.add('is-batch-reveal');
      if (offscreen.has(i)) card.card.classList.add('is-revealed-offscreen');
      const wasAvailable = card.available;
      card.available = i < available;
      card.card.hidden = i < start || i >= end;
      // A card unlocked after mount (the FLIP lane's bonus pair) slides in.
      if (painted && !wasAvailable && card.available) card.card.classList.add('is-arriving');
      const board = state.boards[i];
      const complete = next.masks[i] === 15;
      card.flame.disabled = locked || complete;
      if (next.masks[i]) {
        // Only revealed points may color the flame. Ambiguous historical
        // allocations stay neutral until their recorded total is revealed.
        const points = complete ? board.score : board.quadrants.reduce((sum, quadrant, q) =>
          sum + ((next.masks[i] & (1 << q)) ? quadrant.points || 0 : 0), 0);
        if (complete || board.exact) card.flame.dataset.points = String(points);
        if (!complete) card.flame.setAttribute('aria-label', `Reveal this card (${i + 1}). ${board.exact
          ? `${points} ${points === 1 ? 'point' : 'points'} revealed.`
          : 'Score shown when fully revealed.'}`);
      }
      if (complete && card.flame.dataset.score == null) {
        const score = board.score;
        card.flame.dataset.score = String(score);
        card.flame.textContent = '';
        card.flame.appendChild(el('span', 'dgn-pop__ticket-score', String(score)));
        const label = `Card ${i + 1}: ${score} ${score === 1 ? 'point' : 'points'}. Fully revealed.`;
        card.flame.setAttribute('aria-label', label);
        card.flame.title = label;
        // Only call the formatter once the whole ticket is uncovered. Covered
        // cards must not expose a payout or outcome through their DOM or labels.
        const payout = ticketPayout(rows[i], i);
        if (payout) {
          card.card.classList.add(payout.positive ? 'is-paid' : 'is-miss');
          const payoutLabel = [payout.text, payout.detail].filter(Boolean).join('. ');
          const receipt = el('span', 'dgn-pop__payout');
          receipt.setAttribute('role', 'status');
          receipt.setAttribute('aria-label', `Card ${i + 1}: ${payoutLabel}`);
          receipt.appendChild(el('strong', 'dgn-pop__payout-amount', payout.text));
          if (payout.detail) receipt.appendChild(el('span', 'dgn-pop__payout-detail', payout.detail));
          card.ticket.appendChild(receipt);
          // Keep the amount available after its entrance animation settles.
          card.number.textContent = `CARD ${i + 1} · ${payout.text}`;
          card.number.title = `Card ${i + 1}: ${payoutLabel}`;
        }
      }
      card.cells.forEach((cell, q) => {
        // Keep opened quadrants keyboard-inspectable, with idempotent activation.
        cell.disabled = locked;
        cell.setAttribute('aria-disabled', String(locked || Boolean(next.masks[i] & (1 << q))));
      });
      const wildCount = board.quadrants.filter((q, j) => q.house?.wild && (next.masks[i] & (1 << j))).length;
      const lost = complete && (card.card.classList.contains('is-miss') || board.score <= 2);
      card.gold.hidden = wildCount === 0 || lost;
      const wildText = `${compact ? 'BONUS' : 'WILD BONUS'} ×${(1 + wildCount / 4).toFixed(2)}`;
      if (card.gold.textContent !== wildText) card.gold.textContent = wildText;
    });
    const count = end - start;
    const size = String(count <= 4 ? Math.max(1, count) : 9);
    if (grid.dataset.size !== size) grid.dataset.size = size;
    root.dataset.compact = String(compact);
    root.dataset.ticketSize = available === 1 ? 'single' : 'multi';
    root.dataset.pages = String(compact ? Math.ceil(available / 4) : 1);
    pager.hidden = !compact || available <= 4;
    previous.disabled = locked || page === 0;
    nextPage.disabled = locked || end >= available;
    const rangeLabel = `Cards ${start + 1}–${end} of ${available}`;
    if (pageLabel.textContent !== rangeLabel) pageLabel.textContent = rangeLabel;
    viewport.setAttribute('aria-label', compact ? pageLabel.textContent : 'Cards — scroll for more');
    painted = true;
    // Keyed to the unlocked cards, not the rows: a sealed mystery card must not
    // reveal its three-reel lane through the button's presence.
    all.hidden = next.complete || available <= 1;
    all.disabled = locked;
    all.textContent = compact && available > 4
      ? pageComplete ? (end < available ? 'NEXT CARDS →' : 'UNREVEALED CARDS →') : `REVEAL ${count === 1 ? 'CARD' : `${count} CARDS`}`
      : 'REVEAL ALL';
    const hintText = next.complete ? 'All cards revealed' : compact ? 'Tap or use flame' : 'Tap a quadrant · Flame reveals card';
    if (hint.textContent !== hintText) hint.textContent = hintText;
    return next;
  }
  function commit(added, event) {
    if (!added.length) return;
    const next = paint(added, event);
    sfxDgnPop({ points: Math.max(0, ...added.map(q => q.points || 0)), gold: added.some(q => q.house?.wild), count: added.length });
    onChange(next);
  }
  function reveal(index, mask = 15, event) {
    if (disposed || locked || index >= available) return;
    commit(state.reveal(index, mask), event);
  }
  function revealAll() {
    if (disposed || locked) return;
    onRevealAll();
    commit(cards.flatMap((_, i) => i < available ? state.reveal(i) : []));
  }
  function goToPage(value) {
    if (disposed || locked || !compact) return;
    page = Math.max(0, Math.min(Math.ceil(available / 4) - 1, value));
    // Focus leaves the old card before it becomes hidden. Page changes never
    // reveal results, replay payouts, or advance the parent reveal session.
    viewport.focus?.({ preventScroll: true });
    paint();
  }
  const resize = () => {
    const first = pageRange().start;
    compact = Boolean(phoneQuery.matches);
    page = compact ? Math.floor(first / 4) : 0;
    paint();
  };
  phoneQuery?.addEventListener?.('change', resize);
  cleanups.push(() => phoneQuery?.removeEventListener?.('change', resize));
  paint();
  return {
    element: root, snapshot: state.snapshot, reveal, revealAll,
    setAvailableCount(count) {
      available = Math.max(0, Math.min(rows.length, count));
      page = Math.max(0, Math.min(page, Math.ceil(available / 4) - 1));
      paint();
    },
    setLocked(value) { locked = Boolean(value); paint(); },
    dispose() {
      disposed = true;
      cleanups.forEach(fn => fn());
      root.getAnimations?.({ subtree: true }).forEach(animation => animation.cancel());
      stopDgnPops();
    },
  };
}
